package com.own.order.service;
import com.own.order.repository.SensitiveAccessAuditRepository; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
/** A non-positive retention value disables deletion for legal-hold or investigation environments. */
@Component public class SensitiveAccessAuditRetentionScheduler { private final SensitiveAccessAuditRepository repository; private final int retentionDays; public SensitiveAccessAuditRetentionScheduler(SensitiveAccessAuditRepository repository,@Value("${trade.security.audit-retention-days:180}") int retentionDays){this.repository=repository;this.retentionDays=retentionDays;} @Scheduled(fixedDelayString="${trade.security.audit-retention-delay-millis:86400000}") @Transactional public void purgeExpired(){if(retentionDays<=0)return;repository.deleteByCreatedAtBefore(new Date(System.currentTimeMillis()-retentionDays*24L*3600L*1000L));} }
